UNION ALL SELECT UNISTR('\00AB\0628\064A\0627\0646\0627\062A \062A\062C\0631\0628\0629\00BB: \0644\062A\062C\0631\0628\0629 \0627\0644\0635\0641\062D\0627\062A \0642\0628\0644 \0631\0628\0637 \0623\064A \062C\0647\0627\0632: \0634\0631\0643\0629 \062A\062C\0631\064A\0628\064A\0629 \0641\064A\0647\0627 36 \0645\0648\0638\0641\0627\064B \06485 \0623\062C\0647\0632\0629 \0648\062D\0631\0643\0627\062A \0622\062E\0631 \062E\0645\0633\0629 \0623\0633\0627\0628\064A\0639 \0648\0625\062C\0627\0632\0627\062A \0648\0639\0637\0644\0629. \062A\0635\0644 \062D\0631\0643\0627\062A \0627\0644\064A\0648\0645 \0641\064A \0623\0648\0642\0627\062A\0647\0627 \0645\0627 \062F\0627\0645\062A \0627\0644\0645\0647\0645\0629 \0627\0644\062E\0644\0641\064A\0629 \062A\0639\0645\0644.') AR, 'Sample data: To try the pages before any terminal is connected: a sample company with 36 employees, 5 terminals, five weeks of punches, leave and a holiday. Today''s punches arrive at their times while the background job runs.' EN FROM DUAL
