UNION ALL SELECT UNISTR('\0627\0644\062A\0639\062F\064A\0644 \064A\0628\062F\0623 \0645\0646 \0627\0644\062A\0627\0631\064A\062E \0627\0644\0630\064A \062A\062E\062A\0627\0631\0647 \0648\0644\0627 \064A\063A\064A\0651\0631 \062D\0633\0627\0628 \0627\0644\0623\064A\0627\0645 \0642\0628\0644\0647. \0627\062A\0631\0643 \00AB\0622\062E\0631 \064A\0648\0645\00BB \0641\0627\0631\063A\0627\064B \0644\064A\0628\0642\0649 \0645\0641\062A\0648\062D\0627\064B \062D\062A\0649 \0627\0644\062A\0639\062F\064A\0644 \0627\0644\062A\0627\0644\064A\060C \0623\0648 \062D\062F\062F\0647 \0644\0641\062A\0631\0629 (\0643\0631\0645\0636\0627\0646) \0641\064A\0639\0648\062F \0628\0639\062F\0647\0627 \0645\0627 \0643\0627\0646 \0642\0628\0644\0647. \0627\0644\062A\0639\062F\064A\0644 \0627\0644\062C\062F\064A\062F \064A\064F\0646\0647\064A \0645\0627 \0642\0628\0644\0647 \0641\064A \0627\0644\064A\0648\0645 \0627\0644\0633\0627\0628\0642 \0644\0628\062F\0627\064A\062A\0647.') AR, 'The change starts on the date you choose and leaves the days before it as they were calculated. Leave "Last day" empty to keep it open until the next change, or set it for a period (such as Ramadan): what applied before comes back after it. A new change ends the one before on the day before it starts.' EN FROM DUAL
UNION ALL SELECT UNISTR('\0627\0644\062A\0639\0631\0651\0641 \0627\0644\062A\064A \064A\062A\0639\0644\0651\0645 \0645\0646\0647\0627 \0627\0644\062C\0647\0627\0632 \0627\0644\0648\062C\0647. \0635\0648\0631\0629 JPEG \0623\0642\0644 \0645\0646 400 \0643\064A\0644\0648\0628\0627\064A\062A (\0648\064A\064F\0641\0636\0651\0644 \0646\062D\0648 480 \0628\0643\0633\0644)\061B \062A\064F\0631\0633\0644 \0625\0644\0649') AR, 'recognition photo the terminal learns the face from. A JPEG under 400 KB (about 480 pixels is best); it is sent to the' EN FROM DUAL
UNION ALL SELECT UNISTR('\0627\0644\062A\0646\0628\064A\0647\0627\062A \0645\062A\0648\0642\0641\0629. \064A\0634\063A\0651\0644\0647\0627 \0645\062F\064A\0631 \0627\0644\0646\0638\0627\0645 \0645\0646 \0635\0641\062D\0629 \00AB\0627\0644\062A\0646\0628\064A\0647\0627\062A\00BB.') AR, 'Alerts are off. The system administrator turns them on from the Alerts page.' EN FROM DUAL
