UNION ALL SELECT UNISTR('\062C\0632\0621 \0642\0627\0639\062F\0629 \0627\0644\0628\064A\0627\0646\0627\062A \0623\0642\062F\0645 \0645\0646 \0627\0644\062A\0637\0628\064A\0642. \0634\063A\0651\0644 \0627\0644\0645\0644\0641 oracle_native/apex_workshop_install.sql \0645\0646 SQL Workshop\060C SQL Scripts (\0644\0627 \064A\0645\0633 \0627\0644\0628\064A\0627\0646\0627\062A)\060C \062B\0645 \0623\0639\062F \062A\062D\0645\064A\0644 \0627\0644\0635\0641\062D\0629.') AR, 'The database part is older than the application. Run the file oracle_native/apex_workshop_install.sql in SQL Workshop, SQL Scripts (it leaves the data as it is), then reload the page.' EN FROM DUAL
UNION ALL SELECT UNISTR('\062C\0647\0627\0632 \0628\0644\0627 \0628\0637\0627\0631\064A\0629 \0644\0644\0633\0627\0639\0629 \064A\0628\062F\0623 \0645\0646 \0645\0646\062A\0635\0641 \0627\0644\0644\064A\0644 \062D\064A\0646 \062A\0639\0648\062F \0627\0644\0643\0647\0631\0628\0627\0621\060C \0641\062A\064F\0633\062C\064E\0651\0644 \0628\0635\0645\0629 \0627\0644\0633\0627\0639\0629 8:15 \0639\0644\0649 \0623\0646\0647\0627 00:15 \062D\062A\0649 \062A\064F\0636\0628\0637 \0633\0627\0639\062A\0647 (\0639\0646\062F \0623\0648\0644 \0627\062A\0635\0627\0644 \0628\0627\0644\062E\0627\062F\0645). \0647\0646\0627 \0628\0635\0645\0627\062A \0643\0644 \062C\0647\0627\0632 \0639\0627\062F \0628\0639\062F \0627\0646\0642\0637\0627\0639 \0648\0641\064A\0647\0627 \0645\0627 \0633\064F\062C\0651\0644 \0642\0628\0644 \0636\0628\0637 \0633\0627\0639\062A\0647: \0627\062E\062A\0631 \0628\0635\0645\0629 \062A\0639\0631\0641 \0648\0642\062A\0647\0627 \0627\0644\0635\062D\064A\062D \0648\0627\0643\062A\0628\0647\060C \0641\064A\064F\0636\0627\0641 \0627\0644\0641\0631\0642 \0646\0641\0633\0647 \0625\0644\0649 \0628\0642\064A\0629 \0628\0635\0645\0627\062A \062A\0644\0643 \0627\0644\0639\0648\062F\0629. \0645\0627 \0633\064F\062C\0651\0644 \0628\0639\062F \0636\0628\0637 \0627\0644\0633\0627\0639\0629 \0644\0627 \064A\064F\0645\064E\0633\0651\060C \0648\064A\0628\0642\0649 \0627\0644\0648\0642\062A \0627\0644\0623\0635\0644\064A \0645\062D\0641\0648\0638\0627\064B\060C \0648\064A\064F\0639\0627\062F \062D\0633\0627\0628 \0627\0644\062D\0636\0648\0631.') AR, 'A terminal with no clock battery starts at midnight when the power comes back, so a punch at 8:15 is written 00:15 until its clock is set (on its first contact with the server). Here are the punches of each terminal back after a cut that were recorded before its clock was set: pick one whose right time you know and enter it, and the same difference is added to the others of that return. Nothing recorded after the clock was set is touched, the original time is kept, and attendance is worked out again.' EN FROM DUAL
